    elif args.cmd == "web-read":
        print(hwa.web_read(args.url))
    elif args.cmd == "github-read":
        print(hwa.github_read(args.repo, args.path))
    elif args.cmd == "rss-fetch":
        print(hwa.rss_fetch(args.url))","path":"D:\Portable_Soft\hermes\scripts\hermes_web_access.py"}

